package com.careerpilot.modules.assessment.entity;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="assessment_questions") @Getter @Setter @NoArgsConstructor
public class AssessmentQuestion{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="assessment_id")private Assessment assessment;@Column(name="question_order",nullable=false)private int questionOrder;@Enumerated(EnumType.STRING)@Column(name="question_type",nullable=false,length=30)private QuestionType questionType;@Column(name="question_text",nullable=false,length=1000)private String questionText;@Column(length=1500)private String explanation;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AssessmentDifficulty difficulty;@Column(name="skill_tag",length=120)private String skillTag;@Column(name="selection_category",length=40)private String selectionCategory;@Column(name="created_at",nullable=false)private Instant createdAt;@OneToMany(mappedBy="question",cascade=CascadeType.ALL,orphanRemoval=true)@OrderBy("optionKey")private List<AssessmentOption>options=new ArrayList<>();@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}
